import argparse
import json
import os
import sqlite3
import sys
import time
from datetime import datetime, timedelta
from typing import List, Dict, Any, Optional

def generate_token() -> str:
    return ''.join([f'{i:02x}' for i in os.urandom(8)])

def get_utc_iso8601() -> str:
    return datetime.utcnow().replace(microsecond=0, tzinfo=time.timezone).isoformat() + 'Z'

def parse_filter(filter_str: str) -> Dict[str, str]:
    parts = filter_str.split('=', 1)
    if len(parts) != 2:
        raise ValueError(f"Invalid filter format: {filter_str}")
    column, value = parts
    return {'column': column, 'value': value}

def apply_filters(rows: List[Dict[str, Any]], filters: List[Dict[str, str]]) -> List[Dict[str, Any]]:
    filtered_rows = []
    for row in rows:
        match = True
        for filter_ in filters:
            col = filter_['column']
            val = filter_['value']
            if col == 'id':
                if not isinstance(row[col], int) or row[col] != int(val):
                    match = False
                    break
            else:
                if row[col] != val:
                    match = False
                    break
        if match:
            filtered_rows.append(row)
    return filtered_rows

def serialize_rows(rows: List[Dict[str, Any]]) -> bytes:
    return json.dumps(rows, sort_keys=True).encode('utf-8')

def deserialize_rows(data: bytes) -> List[Dict[str, Any]]:
    return json.loads(data.decode('utf-8'))

def main():
    parser = argparse.ArgumentParser(description='Token Vault')
    subparsers = parser.add_subparsers(dest='command', required=True)

    # Issue command
    issue_parser = subparsers.add_parser('issue', help='Issue a new token')
    issue_parser.add_argument('--db', required=True, help='Database path')
    issue_parser.add_argument('--admin-token', required=True, help='Admin token for authorization')
    issue_parser.add_argument('username', help='Username to issue token for')

    # List command
    list_parser = subparsers.add_parser('list', help='List tokens')
    list_parser.add_argument('--db', required=True, help='Database path')
    list_parser.add_argument('--filter', action='append', help='Filter tokens by column=value or column>value or column<value')
    list_parser.add_argument('--cache', help='Cache path for serialized results')

    args = parser.parse_args()

    if args.command == 'issue':
        if 'TOKENVAULT_ADMIN_TOKEN' not in os.environ:
            print('forbidden', file=sys.stderr)
            sys.exit(1)
        if args.admin_token != os.environ['TOKENVAULT_ADMIN_TOKEN']:
            print('forbidden', file=sys.stderr)
            sys.exit(1)

        conn = sqlite3.connect(args.db)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS tokens (
                id INTEGER PRIMARY KEY,
                username TEXT NOT NULL,
                created_at TEXT NOT NULL,
                expires_at TEXT NOT NULL
            )
        ''')
        token = generate_token()
        created_at = get_utc_iso8601()
        expires_at = (datetime.strptime(created_at, '%Y-%m-%dT%H:%M:%SZ') + timedelta(hours=24)).isoformat() + 'Z'
        cursor.execute('INSERT INTO tokens (username, created_at, expires_at) VALUES (?, ?, ?)',
                      (args.username, created_at, expires_at))
        conn.commit()
        print(token)
        conn.close()
    elif args.command == 'list':
        conn = sqlite3.connect(args.db)
        cursor = conn.cursor()
        cursor.execute('SELECT id, username, created_at, expires_at FROM tokens ORDER BY id ASC')
        rows = [dict(zip(['id', 'username', 'created_at', 'expires_at'], row)) for row in cursor.fetchall()]

        if args.cache:
            cache_path = args.cache
            if os.path.exists(cache_path):
                with open(cache_path, 'rb') as f:
                    cached_data = f.read()
                    rows = deserialize_rows(cached_data)
            else:
                if args.filter:
                    filtered_rows = apply_filters(rows, [parse_filter(f) for f in args.filter])
                    serialized = serialize_rows(filtered_rows)
                    with open(cache_path, 'wb') as f:
                        f.write(serialized)
                else:
                    serialized = serialize_rows(rows)
                    with open(cache_path, 'wb') as f:
                        f.write(serialized)
        else:
            if args.filter:
                filtered_rows = apply_filters(rows, [parse_filter(f) for f in args.filter])
                rows = filtered_rows

        for row in rows:
            print(json.dumps(row))

        conn.close()

if __name__ == '__main__':
    main()
